// La autenticación la hace el propio webhook con una credencial de cabecera:
// n8n Cloud no deja leer variables de entorno desde aquí, y comprobarlo en el
// nodo de entrada es mejor de todos modos porque rechaza antes de ejecutar.
const d = $input.first().json.body || $input.first().json;

const esc = (s) => String(s == null ? '' : s)
  .replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const caliente = d.tier === 'HOT';
const tel = String(d.telefono || '').replace(/\D/g, '');
const ORIGEN = { guia: 'Descargó la guía', cuestionario: 'Rellenó el cuestionario', meta_form: 'Formulario de Meta' };

// El asunto es lo único que se lee desde la pantalla de bloqueo del móvil, así
// que lleva delante lo que decide si hay que abrirlo ahora o luego.
const asunto = (caliente ? '🔥 LEAD HOT · ' : 'Lead nuevo · ')
  + (d.nombre || 'sin nombre')
  + (d.pieza ? ' · ' + d.pieza : '')
  + (d.medidas ? ' ' + d.medidas : '');

const filas = [
  ['Teléfono', d.telefono], ['Email', d.email],
  ['Pieza', d.pieza], ['Dónde va', d.espacio], ['Medidas', d.medidas],
  ['Estilo', d.estilo], ['Presupuesto', d.presupuesto], ['Plazo', d.plazo],
  ['Referencias', d.referencias],
  ['Origen', ORIGEN[d.origen] || d.origen],
  ['Campaña', d.utm_campaign], ['Anuncio', d.utm_content],
].filter(([, v]) => v).map(([k, v]) =>
  `<tr><td style="padding:5px 16px 5px 0;color:#7C7266;vertical-align:top;white-space:nowrap">${esc(k)}</td>`
  + `<td style="padding:5px 0;color:#332B23"><b>${esc(v)}</b></td></tr>`).join('');

const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:15px;line-height:1.55;color:#332B23;max-width:560px">
${caliente ? `<p style="background:#FCE8E6;border-left:3px solid #B3261E;padding:11px 14px;margin:0 0 18px;border-radius:0 6px 6px 0">
<b>Lead HOT.</b> Proyecto definido, presupuesto y plazo cercano.<br>WhatsApp en menos de 2 horas laborables.</p>` : ''}
<h2 style="margin:0 0 2px;font-size:20px;color:#14100D">${esc(d.nombre || 'Sin nombre')}</h2>
<p style="margin:0 0 18px;color:#7C7266;font-size:13px">${esc(ORIGEN[d.origen] || d.origen || '')}</p>
<table style="border-collapse:collapse;font-size:14px">${filas}</table>
<p style="margin:24px 0 0">
${tel ? `<a href="https://wa.me/${tel}" style="background:#8C5E32;color:#fff;padding:11px 20px;border-radius:999px;text-decoration:none;display:inline-block;font-weight:600">Escribir por WhatsApp</a>&nbsp;&nbsp;` : ''}
<a href="https://antic-barcelona-113.vercel.app/crm" style="color:#8C5E32;text-decoration:none">Abrir el CRM →</a></p>
<p style="margin-top:26px;color:#A79C8E;font-size:12px">Antic Barcelona 113 · aviso automático</p></div>`;

return [{ json: { asunto, html, tier: d.tier || '', nombre: d.nombre || '' } }];
